beforeExample:
import static org.junit.Assert.assertFalse;

public class MyTest {
    public void testInequality() {
        int a = 1;
        int b = 2;
        assertFalse(a == b);
    }

    public void testObjectReferenceInequality() {
        Object obj1 = new Object();
        Object obj2 = new Object();
        assertFalse(obj1 == obj2);
    }
}

afterExample:
import static org.junit.Assert.assertNotEquals;

public class MyTest {
    public void testInequality() {
        int a = 1;
        int b = 2;
        assertNotEquals(a, b);
    }

    public void testObjectReferenceInequality() {
        Object obj1 = new Object();
        Object obj2 = new Object();
        assertNotEquals(obj1, obj2);
    }
}

negativeExample:
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class MyTestNegative {
    public void testFalseCondition() {
        boolean condition = false;
        assertFalse(condition); // Different pattern: assertFalse(boolean)
    }

    public void testEquality() {
        int x = 5;
        int y = 5;
        assertTrue(x == y); // Different assertion and pattern
    }

    public void testOtherComparison() {
        String s1 = "hello";
        String s2 = "world";
        assertFalse(s1.equals(s2)); // Different comparison method
    }
}
